import { View, Text, StyleSheet } from "react-native";
import { createContext, useContext } from "react";
import { registerRootComponent } from "expo";

const CartContext = createContext({ count: 0 });

function Badge() {
  const cart = useContext(CartContext);
  return <Text nativeID="badge" style={styles.badge}>Сагс: {cart.count}</Text>;
}

function App() {
  return (
    <CartContext.Provider value={{ count: 5 }}>
      <View style={styles.s}>
        <Badge />
      </View>
    </CartContext.Provider>
  );
}

const styles = StyleSheet.create({ s: { flex: 1, alignItems: "center", justifyContent: "center" }, badge: { fontSize: 22, fontWeight: "bold" } });

registerRootComponent(App);
